import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Build list — what has to exist before the machine can find a kernel","description":"","frontmatter":{"title":"Build list — what has to exist before the machine can find a kernel","type":"report","date":"2026-10-27T00:00:00.000Z","status_note":"proposed · dependency-ordered · M1 scope only"},"headers":[],"relativePath":"graphopt/project/reports/2026-10-27-build-list-m1.md","filePath":"vendored/graphopt/project/reports/2026-10-27-build-list-m1.md"}`),a={name:`graphopt/project/reports/2026-10-27-build-list-m1.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="build-list-—-what-has-to-exist-before-the-machine-can-find-a-kernel" tabindex="-1">Build list — what has to exist before the machine can find a kernel <a class="header-anchor" href="#build-list-—-what-has-to-exist-before-the-machine-can-find-a-kernel" aria-label="Permalink to “Build list — what has to exist before the machine can find a kernel”">​</a></h1><p><strong>Refactor context:</strong> lab-form per ADR-0159; ADR-0160 allocates the IR. <strong>Visibility (ADR-0150):</strong> <code>lib-kernel-ir</code> public; <code>compile-triton</code>, <code>lib-triton</code>, <code>ext-opt-*</code> private until done. <strong>Definition of done:</strong> the four <code>split_k</code> variants of <code>qgemv</code> are <em>generated from IR terms</em> (not written by hand), all agree with <code>awq_gemm</code> (cosine ≥ 0.9999), and at least one matches the hand-written kernel&#39;s cold time on <code>down_proj</code> (58.9 µs).</p><table tabindex="0"><thead><tr><th>#</th><th>build</th><th>why it is needed first</th><th>home</th><th>effort</th><th>gate</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong>ADR-0160: the kernel IR is <code>Term</code> + kit-declared ops</strong></td><td>the kernel&#39;s six combinators stay closed; the IR enters as data, and the decision must be recorded where the IR lives</td><td><code>opt-kernel</code> (today <code>kernelopt</code>)</td><td>1 h</td><td>ADR accepted</td></tr><tr><td><strong>2</strong></td><td><strong><code>lib-kernel-ir</code></strong> — the vocabulary as a handl <em>lib</em>: nine ops, grades, costs, <strong>and a torch denotation per op</strong></td><td>the vocabulary the search ranges over; denotations make &quot;equal meaning&quot; checkable instead of a slogan</td><td>new repo — <strong>public</strong></td><td>1 d</td><td>every op has a signature, a grade row, a cost, a reference function</td></tr><tr><td><strong>3</strong></td><td><strong><code>compile-triton</code></strong> — Rust engine: <code>Term</code> → Triton, for <strong><code>qgemv</code> and <code>gate_proj</code></strong>, 4 <code>split_k</code> variants each</td><td>the lowering that makes terms runnable; two opposite geometries stop it overfitting one shape</td><td>new repo — <strong>private</strong> (tooling tier, ADR-0150)</td><td>2 d</td><td>8 variants compile and run</td></tr><tr><td><strong>4</strong></td><td><strong>Equality gate vs the incumbent</strong></td><td>the AWQ nibble-order bug survived because the reference shared the assumption; comparison must be against <code>awq_gemm</code>, never our own reimplementation</td><td><code>graphopt/bench</code></td><td>½ day</td><td>cosine ≥ 0.9999 on every variant</td></tr><tr><td><strong>5</strong></td><td><strong>Search driver in <code>kernelopt</code></strong></td><td>enumerates <code>Term</code>s, applies the equality gate, prices with the roofline bound, then measures with the deploy referee</td><td><code>kernelopt</code></td><td>1 d</td><td>emits a best kernel per operator + a routing row</td></tr></tbody></table><p><strong>Total to M1:</strong> ~5 days.</p><p><strong>No kit in M1.</strong> A kit assembles several libs; one lib is loaded directly. <code>kit-kernel-ir</code> arrives at M2, when <code>lib-triton-qgemv</code> (the binding), the cost tables and the base types have to meet — the same reason <code>kit-prelude-lang</code> exists and a lone lib does not.</p><h2 id="deliberately-not-in-m1" tabindex="-1">Deliberately not in M1 <a class="header-anchor" href="#deliberately-not-in-m1" aria-label="Permalink to “Deliberately not in M1”">​</a></h2><ul><li><strong><code>lib-triton-qgemv</code> binding.</strong> Needed to <em>ship</em> the kernel through the platform, not to <em>find</em> it. Deferred until the search proves it can find one worth shipping.</li><li><strong>M &gt; 1 tiling / prefill, FP8, GPTQ layouts.</strong> Coverage work; it only makes sense once both operators are proven.</li><li><strong>Compile cache and pipelining combinators.</strong> Both are required for <em>scale</em> (~10⁴ candidates) but not for the M1 gate (4 variants). Flagged so they are not forgotten: without a cache the search is rate-limited by Triton compilation.</li><li><strong>Static cost ranking.</strong> The model is used only as a hard bound (roofline floor, legality). This week&#39;s evidence: warm-cache ranking contradicted deploy ranking on three of four shapes.</li></ul><h2 id="what-the-m1-result-would-settle" tabindex="-1">What the M1 result would settle <a class="header-anchor" href="#what-the-m1-result-would-settle" aria-label="Permalink to “What the M1 result would settle”">​</a></h2><p>If a fixed lowering matches the hand kernel on <code>qgemv</code> and reaches parity on <code>gate_proj</code>, generalising is worth it and the search has a substrate. If it cannot, no amount of IR generality will help — a codegen that loses to 30 lines of hand-written Triton will lose at scale too, and the honest response is to keep hand-writing kernels and use the search only for configs.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};